import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    F = int(input_data[1])

    grid = [list(input_data[i + 2]) for i in range(N)]

    if int(grid[0][0]) <= F:
        grid[0][0] = '*'
        queue = deque([(0, 0)])

        while queue:
            r, c = queue.popleft()

            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if grid[nr][nc] != '*' and int(grid[nr][nc]) <= F:
                        grid[nr][nc] = '*'
                        queue.append((nr, nc))

    sys.stdout.write('\n'.join(''.join(row) for row in grid) + '\n')

if __name__ == '__main__':
    main()
